Account.ready.then(user=>{
 if(user.role!=='admin')return;
 const section=document.createElement('section');section.className='editor';section.id='feedback';
 section.innerHTML='<h2>Learner feedback</h2><p>Review public comments and messages sent to admin. Private study notes are never shown here. Decisions on public comments are public; decisions on private feedback are visible only to its author and admins.</p><label>Review status<select id="review-filter"><option value="open">Awaiting review</option><option value="all">All feedback</option><option>New</option><option>Under review</option><option>Resolved</option></select></label><button class="secondary" id="refresh-feedback">Refresh feedback</button><p id="review-message" role="status"></p><div id="feedback-inbox"></div>';
 document.body.append(section);
 const $=id=>document.getElementById(id);let items=[];const drafts=new Set();
 window.addEventListener('beforeunload',e=>{if(drafts.size){e.preventDefault();e.returnValue=''}});
 function render(){const filter=$('review-filter').value;const found=items.filter(x=>filter==='all'||filter==='open'&&x.status!=='Resolved'||x.status===filter);$('feedback-inbox').replaceChildren();
 for(const x of found){const card=document.createElement('article');card.style.minHeight='0';card.style.margin='18px 0';const title=document.createElement('h3');title.textContent=x.question_id+' · '+(x.kind==='public'?'Public discussion':'Private feedback to admin');const meta=document.createElement('p');meta.textContent=x.author+' · '+x.created+' · '+(x.question_revision?'Question revision '+x.question_revision:'Earlier question revision not recorded');const body=document.createElement('p');body.style.whiteSpace='pre-wrap';body.textContent=x.body;
 const form=document.createElement('form');const label=document.createElement('label');label.textContent='Review status';const status=document.createElement('select');for(const value of ['New','Under review','Resolved'])status.add(new Option(value,value));status.value=x.status;label.append(status);
 const decisionLabel=document.createElement('label');decisionLabel.textContent='Decision / explanation';const decision=document.createElement('textarea');decision.rows=3;decision.maxLength=5000;decision.value=x.decision||'';decisionLabel.append(decision);
 const hint=document.createElement('p');hint.textContent='Explain the outcome before resolving. Changing this review does not change the answer key or past scores. Use the question editor to correct the key.';
 const button=document.createElement('button');button.className='primary';button.textContent='Save review';const message=document.createElement('p');message.setAttribute('role','status');form.append(label,decisionLabel,hint,button,message);form.oninput=()=>{drafts.add(x.id)};
 form.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{await Account.request('/api/admin/feedback-review',{id:x.id,status:status.value,decision:decision.value,revision:x.review_revision});x.status=status.value;x.decision=decision.value;x.review_revision++;message.textContent='Review saved. Refresh to see updated history.';drafts.delete(x.id);}catch(err){message.textContent=err.message}finally{button.disabled=false}};
 const history=document.createElement('details');const heading=document.createElement('summary');heading.textContent='Review history ('+x.reviews.length+')';history.append(heading);for(const event of x.reviews){const p=document.createElement('p');p.style.whiteSpace='pre-wrap';p.textContent=event.created+' · '+event.status+(event.decision?' — '+event.decision:'');history.append(p)}
 card.append(title,meta,body,form,history);$('feedback-inbox').append(card);
 }if(!found.length)$('feedback-inbox').textContent='No feedback matches this filter.';}
 async function load(){if(drafts.size&&!confirm('Discard unsaved review changes and refresh?'))return;try{items=await Account.request('/api/admin/feedback');drafts.clear();render();$('review-message').textContent='Updated.'}catch(e){$('review-message').textContent=e.message}}
 $('refresh-feedback').onclick=load;$('review-filter').onchange=()=>{if(drafts.size&&!confirm('Discard unsaved review changes?'))return;drafts.clear();render()};load();if(location.hash==='#feedback')section.scrollIntoView();
}).catch(()=>{});
